@Test
public void testSortingWithPreMerge() {
    // Save the original value...
    int origMaxSpillFiles = SortedDataBag.MAX_SPILL_FILES;
    try {
        // Vary the number of spill files and bindings so we get a variable number of premerge rounds
        // @formatter:off
        SortedDataBag.MAX_SPILL_FILES = 2;
        testSorting(1, 1);
        SortedDataBag.MAX_SPILL_FILES = 2;
        testSorting(2, 1);
        SortedDataBag.MAX_SPILL_FILES = 2;
        testSorting(3, 1);
        SortedDataBag.MAX_SPILL_FILES = 2;
        testSorting(4, 1);
        SortedDataBag.MAX_SPILL_FILES = 2;
        testSorting(5, 1);
        SortedDataBag.MAX_SPILL_FILES = 2;
        testSorting(1, 10);
        SortedDataBag.MAX_SPILL_FILES = 2;
        testSorting(1000, 10);
        SortedDataBag.MAX_SPILL_FILES = 100;
        testSorting(1000, 10);
        SortedDataBag.MAX_SPILL_FILES = 2;
        testSorting(10, 10);
        SortedDataBag.MAX_SPILL_FILES = 5;
        testSorting(10, 10);
        // @formatter:on
    } finally {
        SortedDataBag.MAX_SPILL_FILES = origMaxSpillFiles;
    }
}

@Test
public void testTemporaryFilesAreCleanedUpAfterCompletion() {
    List<Binding> unsorted = randomBindings(500);
    List<SortCondition> conditions = new ArrayList<>();
    conditions.add(new SortCondition(new ExprVar("8"), Query.ORDER_ASCENDING));
    BindingComparator comparator = new BindingComparator(conditions);
    SortedDataBag<Binding> db = new SortedDataBag<>(new ThresholdPolicyCount<Binding>(10), SerializationFactoryFinder.bindingSerializationFactory(), comparator);
    List<File> spillFiles = new ArrayList<>();
    try {
        db.addAll(unsorted);
        spillFiles.addAll(db.getSpillFiles());
        int count = 0;
        for (File file : spillFiles) {
            if (file.exists()) {
                count++;
            }
        }
        // 500 bindings divided into 50 chunks (49 in files, and 1 in memory)
        assertEquals(49, count);
        Iterator<Binding> iter = db.iterator();
        while (iter.hasNext()) {
            iter.next();
        }
        Iter.close(iter);
    } finally {
        db.close();
    }
    int count = 0;
    for (File file : spillFiles) {
        if (file.exists()) {
            count++;
        }
    }
    assertEquals(0, count);
}

