// Example from RFC 2617
@Test
public void digest_1() {
    String header = "Digest realm=\"testrealm@host.com\", qop=\"auth,auth-int\"," + " nonce=\"dcd98b7102dd2f0e8b11d0f600bfb0c093\"," + " opaque=\"5ccc069c403ebaf9f0171e9517f40e41\"";
    AuthChallenge aHeader = AuthChallenge.parse(header);
    String requestTarget = "/dir/index.html";
