/**
 * Tests for the {@link Query} clone method.
 * Data and path blocks are mutable elements and modifications after a clone
 * should be possible independently.
 */
@Test
public void testCloneOfDataAndPathBlocks() {
    String str = "PREFIX eg: <http://www.example.org/> " + "SELECT * { ?s eg:foo/eg:bar ?o VALUES (?s ?o) { (eg:baz 1) } }";
    Query query = QueryFactory.create(str);
    Query clone = TestQueryCloningEssentials.checkedClone(query);
    // Modification of the query pattern must not change the original query
    {
        Query cloneOfClone = clone.cloneQuery();
        ElementPathBlock elt = (ElementPathBlock) ((ElementGroup) cloneOfClone.getQueryPattern()).get(0);
        elt.addTriple(Triple.create(RDF.Nodes.type, RDF.Nodes.type, RDF.Nodes.Property));
        Assert.assertNotEquals(elt, query);
    }
    // After modifying the clone of a clone the initial clone must match the original query
    Assert.assertEquals(query, clone);
    // Modification of the value block must not change the original query
    {
        Query cloneOfClone = clone.cloneQuery();
        ElementData elt = (ElementData) ((ElementGroup) cloneOfClone.getQueryPattern()).get(1);
        elt.getRows().add(BindingFactory.empty());
        Assert.assertNotEquals(query, cloneOfClone);
    }
    Assert.assertEquals(query, clone);
}

@Test
public void testCloneOfValuesDataBlock() {
    String str = "PREFIX eg: <http://www.example.org/> " + "SELECT * { ?s eg:foo/eg:bar ?o } VALUES (?s ?o) { (eg:baz 1) }";
    Query query = QueryFactory.create(str);
    // Modifying a clone's value data block must not affect that of the original query.
    Query clone = TestQueryCloningEssentials.checkedClone(query);
    Assert.assertEquals(query.getValuesData(), clone.getValuesData());
    Var x = Var.alloc("x");
    clone.setValuesDataBlock(List.of(x), List.of(BindingFactory.binding(x, NodeFactoryExtra.intToNode(1))));
    Assert.assertNotEquals(query.getValuesData(), clone.getValuesData());
}

@Test
public void runTest() {
    silenceWarnings(() -> checkedClone(query));
}

@Test
public void testIterator() throws IOException {
    Model model = ModelFactory.createDefaultModel();
    {
        Resource r = model.createResource(AnonId.create("first"));
        Property p = model.getProperty("");
        RDFNode node = ResourceFactory.createTypedLiteral("123", XSDDatatype.XSDdecimal);
        model.add(r, p, node);
        r = model.createResource(AnonId.create("second"));
        p = model.getProperty("");
        node = ResourceFactory.createTypedLiteral("abc", XSDDatatype.XSDstring);
        model.add(r, p, node);
        r = model.createResource(AnonId.create("third"));
        p = model.getProperty("");
        node = ResourceFactory.createLangLiteral("def", "en");
        model.add(r, p, node);
        r = model.createResource(AnonId.create("fourth"));
        p = model.getProperty("");
        node = ResourceFactory.createTypedLiteral("true", XSDDatatype.XSDboolean);
        model.add(r, p, node);
    }
    Query query = QueryFactory.create("JSON { \"s\": ?s , \"p\": ?p , \"o\" : ?o } " + "WHERE { ?s ?p ?o }", Syntax.syntaxARQ);
    try (QueryExecution qexec = QueryExecutionFactory.create(query, model)) {
        Iterator<JsonObject> execJsonItems = qexec.execJsonItems();
        try (final ByteArrayOutputStream baos = new ByteArrayOutputStream()) {
            ResultSetFormatter.output(baos, execJsonItems);
            String output = baos.toString(Charset.forName("UTF-8"));
            assertTrue(output.contains("\"_:first\""));
            assertTrue(output.contains("\"_:second\""));
            assertTrue(output.contains("\"_:third\""));
            assertTrue(output.contains("\"_:fourth\""));
            assertFalse(output.contains("\"true\""));
            assertTrue(output.contains("true"));
            assertTrue(output.contains("123"));
            assertFalse(output.contains("\"123\""));
            assertTrue(output.contains("\"abc\""));
        }
    }
}

