@Test
public void testCache1() {
    FileManager fileManager = FileManager.create();
    fileManager.addLocatorFile(testingDir);
    Model m1 = fileManager.loadModelInternal(fileModel);
    Model m2 = fileManager.loadModelInternal(fileModel);
    assertNotSame(m1, m2);
}

@Test
public void testCache2() {
    FileManager.setGlobalFileManager(AdapterFileManager.get());
    FileManager fileManager = FileManager.getInternal();
    fileManager.addLocatorFile(testingDir);
    fileManager.setModelCaching(true);
    Model m1 = fileManager.loadModelInternal(fileModel);
    Model m2 = fileManager.loadModelInternal(fileModel);
    assertSame(m1, m2);
}

@Test
public void testCache3() {
    FileManager fileManager = FileManager.getInternal();
    fileManager.addLocatorFile(testingDir);
    fileManager.setModelCaching(true);
    Model m1 = fileManager.loadModelInternal(fileModel);
    Model m2 = fileManager.loadModelInternal(fileModel);
    assertSame(m1, m2);
    fileManager.removeCacheModel(fileModel);
    Model m3 = fileManager.loadModelInternal(fileModel);
    assertNotSame(m1, m3);
    fileManager.resetCache();
    Model m4 = fileManager.loadModelInternal(fileModel);
    Model m5 = fileManager.loadModelInternal(fileModel);
    assertSame(m4, m5);
    assertNotSame(m1, m4);
    assertNotSame(m3, m4);
}

@Test
public void tuple_0() {
    long count = parseCount("");
    assertEquals(0, count);
}

@Test
public void tuple_1() {
    long count = parseCount("<x> <y> <z>.");
    assertEquals(1, count);
}

@Test
public void tuple_2() {
    long count = parseCount("<x> <y> \"z\".");
    assertEquals(1, count);
}

@Test
public void tuple_3() {
    long count = parseCount("<x> <y> <z>. <x> <y> <z>.");
    assertEquals(2, count);
}

@Test
public void tuple_4() {
    long count = parseCount("<x> <y> \"123\"^^<int>.");
    assertEquals(1, count);
}

@Test
public void tuple_5() {
    long count = parseCount("<x> <y> \"123\"@lang.");
    assertEquals(1, count);
}

// Test parse errors interface.
@Test(expected = ExFatal.class)
public void tuple_bad_01() {
    // No DOT
    parseCount("<x> <y> <z>");
}

@Test(expected = ExFatal.class)
public void tuple_bad_02() {
    // Bad predicate
    parseCount("<x> _:a <z> .");
}

@Test(expected = ExFatal.class)
public void tuple_bad_03() {
    // Bad predicate
    parseCount("<x> \"p\" <z> .");
}

@Test(expected = ExFatal.class)
public void tuple_bad_4() {
    // Bad subject
    parseCount("\"x\" <p> <z> .");
}

@Test(expected = ExFatal.class)
public void tuple_bad_5() {
    // No variables
    parseCount("<x> <p> ?var .");
}

@Test(expected = ExFatal.class)
public void tuple_bad_6() {
    // No abbreviations.
    parseCount("<x> <p> 123 .");
}

@Test(expected = ExFatal.class)
public void tuple_bad_7() {
    // No prefixed names
    parseCount("<x> <p> x:y .");
}

// Bad terms - but accepted by default.
@Test(expected = ExError.class)
public void tuple_bad_10() {
    parseCount("<x> <p> <bad uri> .");
}

// Bad terms (value range) - but legal syntax
@Test
public void tuple_bad_11() {
    parseCount("<x> <p> \"9000\"^^<http://www.w3.org/2001/XMLSchema#byte> .");
}

// Bad - relative URI.
@Test(expected = ExError.class)
public void tuple_bad_21() {
    parseCheck("<x> <p> <z> .");
}

// Bad terms
@Test(expected = ExFatal.class)
public void tuple_bad_22() {
    parseCheck("<http://example/x> <http://example/p> \"abc\"^^<http://example/bad uri> .");
}

@Test(expected = ExWarning.class)
public void tuple_bad_23() {
    parseCheck("<http://example/x> <http://example/p> \"9000\"^^<http://www.w3.org/2001/XMLSchema#byte> .");
}

// ASCII vs UTF-8
@Test
public void tuple_charset_1() {
    // E9 is e-acute
    parseCheck("<http://example/x\\u00E9> <http://example/p> <http://example/s> .");
}

@Test
public void tuple_charset_2() {
    parseCheck("<http://example/é> <http://example/p> \"é\" .");
}

