    InputStream in = IO.openFile(fInput);
    DatasetGraph dsg = DatasetGraphFactory.create();
    //StreamRDF stream = StreamRDFLib.writer(System.out) ;
    StreamRDF stream = StreamRDFLib.dataset(dsg);
