    Triple t = SSE.parseTriple("(_:b _:b _:c)");
    Triple t1 = roundTrip(t);
    assertEquals(t, t1);
    assertEquals(t1.getSubject(), t1.getPredicate());
    assertNotEquals(t1.getSubject(), t1.getObject());
    assertTrue(t1.getSubject().isBlank());
}

