    assertNotEquals(q.getSubject(), q1.getObject());
}

@Test
public void serialize_quad_03() throws Exception {
    Quad q = SSE.parseQuad("(<_:abc> ?y ?x <_:abc>)");
    Quad q1 = roundTrip(q);
    assertEquals(q, q1);
    assertEquals(q.getGraph(), q1.getObject());
}

@Test
public void serialize_quad_04() throws Exception {
    Quad q = SSE.parseQuad("(<_:abc> <_:abc> <_:def> <_:abc>)");
    Quad q1 = roundTrip(q);
    assertEquals(q, q1);
    assertEquals(q.getSubject(), q1.getObject());
    assertNotEquals(q.getSubject(), q1.getPredicate());
}

@Test
public void stream_count_01() {
    StreamRDFCounting stream = StreamRDFLib.count();
    stream.start();
    assertEquals(0, stream.count());
    stream.triple(triple1);
    assertEquals(1, stream.count());
    stream.triple(triple1);
    assertEquals(2, stream.count());
    stream.finish();
    assertEquals(2, stream.count());
    assertEquals(2, stream.countTriples());
    assertEquals(0, stream.countQuads());
}

@Test
public void stream_count_02() {
    StreamRDFCounting stream = StreamRDFLib.count();
    stream.start();
    stream.triple(triple1);
    stream.quad(quad1);
    assertEquals(2, stream.count());
    assertEquals(1, stream.countTriples());
    assertEquals(1, stream.countQuads());
    stream.finish();
}

