@Test
public void testEncodedUTF8() {
    Iterator<Triple> it = RDFDataMgr.createIteratorTriples(new ByteArrayInputStream(Bytes.asUTF8bytes("<a> <b> \"\\u263A\" .")), RDFLanguages.NTRIPLES, null);
    assertTrue(it.hasNext());
    assertEquals("☺", it.next().getObject().getLiteralLexicalForm());
}

@Test
public void testRawUTF8() {
    Iterator<Triple> it = RDFDataMgr.createIteratorTriples(new ByteArrayInputStream(Bytes.asUTF8bytes("<a> <b> \"☺\" .")), RDFLanguages.NTRIPLES, null);
    assertTrue(it.hasNext());
