    // Answer when reorder BGPs before general filter placements.
    String expected = StrUtils.strjoinNL("(filter (!= ?VAR 123)", "  (disjunction", "      (assign ((?var3 'ABC'))", "        (filter (regex ?var4 'pat1')", "          (bgp", "            (triple ?var2 <http://example/p2> 'ABC')", "            (triple ?var2 <http://example/p1> ?var4)", "          )))", "      (assign ((?var3 'XYZ'))", "        (filter (regex ?var4 'pat1')", "          (bgp", "           (triple ?var2 <http://example/p2> 'XYZ')", "            (triple ?var2 <http://example/p1> ?var4)", "         )))))");
    // 2022-11: JENA-2317 (reorder BGPs in the algebra optimizer) is causing problems
    // because it does not consider variables flowing into a BGP (OpSequence, EXISTS).
    // For now, it defaults to off.
    //checkAlgebra(in, expected);
    // Before JENA-2317 when BGP reordering was done in the algebra optimization phase.
    String expectedNoReorderBGP = StrUtils.strjoinNL("(filter (!= ?VAR 123)", " (disjunction", "   (assign ((?var3 'ABC'))", "     (sequence", "       (filter (regex ?var4 'pat1')", "         (bgp (triple ?var2 :p1 ?var4)))", "       (bgp (triple ?var2 :p2 'ABC'))))", "   (assign ((?var3 'XYZ'))", "     (sequence", "       (filter (regex ?var4 'pat1')", "         (bgp (triple ?var2 :p1 ?var4)))", "       (bgp (triple ?var2 :p2 'XYZ'))))))");
    checkAlgebra(in, expectedNoReorderBGP);
}

