    String y = StrUtils.strjoinNL("(filter (< (+ ?o ?o1) 999)", "  (join", "    (filter ((= 13 14) (< ?o 56))", "      (bgp (triple ?s ?p ?o)))", "    (filter ((= 13 14) (> ?o1 12))", "      (bgp (triple ?s ?p1 ?o1)))))");
