    String y1 = StrUtils.strjoinNL("(filter (< (+ ?o ?o1) 999)", "  (join", "  (filter (< ?o 56)", "    (sequence", "      (filter (= 13 14)", "        (table unit))", "      (bgp (triple ?s ?p ?o))))", "  (filter (> ?o1 12)", "    (sequence", "      (filter (= 13 14)", "        (table unit))", "      (bgp (triple ?s ?p1 ?o1))))", "   ))");
    test(x, y1);
}

