    // Transformation if filter place not happening.
    // Weaker placement.
    String ops = StrUtils.strjoinNL("(assign ((?x <http://example/x>))", "   (sequence", "       (conditional", "         (table unit)", "         (bgp (triple <http://example/x> <http://example/q> ?o)))", "       (bgp (triple <http://example/x> <http://example/p> ?o2))))");
    //JENA-671
    // Note that "assign" is a filter as well
    // so it filters the ?x from the RHS of the conditional.
    String ops2 = StrUtils.strjoinNL("(sequence", "  (conditional", "    (table unit)", "    (bgp (triple ?x <http://example/q> ?o)) )", "  (assign ((?x <http://example/x>))", "    (bgp (triple <http://example/x> <http://example/p> ?o2)))", "  )");
    check(qs, ops2);
}

