@Test
public void testLangCompareAlways1() {
    // @de before @en => "'abc'@en" > "'bcd'@de" => +1
    NodeValue nv1 = parse("'abc'@en");
    NodeValue nv2 = parse("'bcd'@de");
    assertEquals(Expr.CMP_GREATER, NodeCmp.compareRDFTerms(nv1.getNode(), nv2.getNode()));
