    Integer[] expectedPut = { 2, 0, 1 };
    assertEquals(Arrays.asList(expectedPut), map.transformPut());
    Integer[] expectedGet = { 1, 2, 0 };
    assertEquals(Arrays.asList(expectedGet), map.transformGet());
}

