@Test
public void testCloseOfTabledIterator() {
    Model m = ModelFactory.createDefaultModel();
    String data = StrUtils.strjoinNL("@prefix rdfs:  <http://www.w3.org/2000/01/rdf-schema#> .", "@prefix rdf:   <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .", "", "<urn:ic:x1> rdf:type <urn:ic:SUB> .", "<urn:ic:SUB> rdfs:subClassOf <urn:ic:CLASS> .");
    m.read(new ByteArrayInputStream(data.getBytes(StandardCharsets.UTF_8)), "", "Turtle");
    String rules = "-> table(rdf:type). (?a rdf:type <urn:ic:CLASS>) <- (?a rdf:type <urn:ic:SUB>) .";
    Reasoner reasoner = new GenericRuleReasoner(Rule.parseRules(rules));
    InfModel infModel = ModelFactory.createInfModel(reasoner.bind(m.getGraph()));
    Graph infGraph = infModel.getGraph();
    Node x1 = NodeFactory.createURI("urn:ic:x1");
    Node clsSUB = NodeFactory.createURI("urn:ic:SUB");
    Node clsCLASS = NodeFactory.createURI("urn:ic:CLASS");
    ExtendedIterator<Triple> sInfIter = infGraph.find(x1, RDF.Nodes.type, clsSUB);
    assertTrue(sInfIter.hasNext());
    // Closing without having read from the iterator
    // Forces a close of LPInterpreter instances including on behind the tabled goal for the find
    sInfIter.close();
    // This query depends on the above tabled goal which was not complete before the close()
    ExtendedIterator<Triple> cInfIter = infGraph.find(x1, RDF.Nodes.type, clsCLASS);
    boolean foundClass = cInfIter.hasNext();
    assertTrue(foundClass);
}

@Test
public void testTabledGoalsCacheHits() throws Exception {
    Graph data = GraphMemFactory.createGraphMem();
    data.add(Triple.create(a, ty, C1));
    List<Rule> rules = Rule.parseRules("[r1:  (?x p ?t) <- (?x rdf:type C1), makeInstance(?x, p, C2, ?t)]" + "[r2:  (?t rdf:type C2) <- (?x rdf:type C1), makeInstance(?x, p, C2, ?t)]");
    FBRuleInfGraph infgraph = (FBRuleInfGraph) createReasoner(rules).bind(data);
    LPBRuleEngine engine = getEngineForGraph(infgraph);
    assertEquals(0, engine.activeInterpreters.size());
    assertEquals(0, engine.tabledGoals.size());
    ExtendedIterator<Triple> it = infgraph.find(a, ty, C1);
    while (it.hasNext()) {
        it.next();
        // This was needed prior to JENA-2184 to make this test work at all.
        // Leaving in place so that the following assert is a test that a fully
        // generated tabled goal does remain in the table and doesn't get removed
        // by the following close()
    }
    it.close();
    // how many were cached
    assertEquals(1, engine.tabledGoals.size());
    // and no leaks of activeInterpreters
    assertEquals(0, engine.activeInterpreters.size());
    // Now ask again:
    it = infgraph.find(a, ty, C1);
    while (it.hasNext()) {
        it.next();
    }
    it.close();
    // if it was a cache hit, no change here:
    assertEquals(1, engine.tabledGoals.size());
    assertEquals(0, engine.activeInterpreters.size());
}

@Test
public void testTabledGoalsLeak() throws Exception {
    Graph data = GraphMemFactory.createGraphMem();
    data.add(Triple.create(a, ty, C1));
    List<Rule> rules = Rule.parseRules("[r1:  (?x p ?t) <- (?x rdf:type C1), makeInstance(?x, p, C2, ?t)]" + "[r2:  (?t rdf:type C2) <- (?x rdf:type C1), makeInstance(?x, p, C2, ?t)]");
    FBRuleInfGraph infgraph = (FBRuleInfGraph) createReasoner(rules).bind(data);
    LPBRuleEngine engine = getEngineForGraph(infgraph);
    assertEquals(0, engine.activeInterpreters.size());
    assertEquals(0, engine.tabledGoals.size());
    ExtendedIterator<Triple> it = infgraph.find(a, ty, C1);
    it.close();
    // how many were cached - in current configuration this will be zero because we retract the cache entry, in other settings might be one completed goal
    assertTrue(engine.tabledGoals.size() <= 1);
    // and no leaks of activeInterpreters
    assertEquals(0, engine.activeInterpreters.size());
    // Now ask again:
    it = infgraph.find(a, ty, C1);
    it.close();
    // if it was a cache hit, no change here:
    assertTrue(engine.tabledGoals.size() <= 1);
    assertEquals(0, engine.activeInterpreters.size());
    //the cached generator should not have any consumingCP left
    engine.tabledGoals.keys().forEachRemaining(tp -> {
        Generator generator = engine.tabledGoals.getIfPresent(tp);
        assertEquals(0, generator.consumingCPs.size());
    });
}

@Test
public void testSaturateTabledGoals() throws Exception {
    final int MAX = 1024;
    // Set the cache size very small just for this test
    System.setProperty("jena.rulesys.lp.max_cached_tabled_goals", "" + MAX);
    try {
        Graph data = GraphMemFactory.createGraphMem();
        data.add(Triple.create(a, ty, C1));
        List<Rule> rules = Rule.parseRules("[r1:  (?x p ?t) <- (?x rdf:type C1), makeInstance(?x, p, C2, ?t)]" + "[r2:  (?t rdf:type C2) <- (?x rdf:type C1), makeInstance(?x, p, C2, ?t)]");
        FBRuleInfGraph infgraph = (FBRuleInfGraph) createReasoner(rules).bind(data);
        LPBRuleEngine engine = getEngineForGraph(infgraph);
        assertEquals(0, engine.activeInterpreters.size());
        assertEquals(0, engine.tabledGoals.size());
        // JENA-901
        // Let's ask about lots of unknown subjects
        for (int i = 0; i < MAX * 128; i++) {
            Node test = NodeFactory.createURI("test" + i);
            ExtendedIterator<Triple> it = infgraph.find(test, ty, C2);
            assertFalse(it.hasNext());
            it.close();
        }
        // Let's see how many were cached - should be MAX or less (less if a GC freed weak values in the cache).
        assertTrue(engine.tabledGoals.size() <= MAX);
        // and no leaks of activeInterpreters (this will happen if we forget
        // to call hasNext above)
        assertEquals(0, engine.activeInterpreters.size());
    } finally {
        System.clearProperty("jena.rulesys.lp.max_cached_tabled_goals");
    }
}

@Test
public void testNotLeakingActiveInterpreters() throws Exception {
    Graph data = GraphMemFactory.createGraphMem();
    data.add(Triple.create(a, ty, C1));
    data.add(Triple.create(b, ty, C1));
    List<Rule> rules = Rule.parseRules("[r1:  (?x p ?t) <- (?x rdf:type C1), makeInstance(?x, p, C2, ?t)]" + "[r2:  (?t rdf:type C2) <- (?x rdf:type C1), makeInstance(?x, p, C2, ?t)]");
    FBRuleInfGraph infgraph = (FBRuleInfGraph) createReasoner(rules).bind(data);
    LPBRuleEngine engine = getEngineForGraph(infgraph);
    assertEquals(0, engine.activeInterpreters.size());
    assertEquals(0, engine.tabledGoals.size());
    // we ask for a non-hit -- it works, but only because we call it.hasNext()
    ExtendedIterator<Triple> it = infgraph.find(nohit, ty, C1);
    assertFalse(it.hasNext());
    it.close();
    assertEquals(0, engine.activeInterpreters.size());
    // and again.
    // Ensure this is not cached by asking for a different triple pattern
    ExtendedIterator<Triple> it2 = infgraph.find(nohit, ty, C2);
    // uuups, forgot to call it.hasNext(). But .close() should tidy
    it2.close();
    assertEquals(0, engine.activeInterpreters.size());
    // OK, let's ask for something that is in the graph
    ExtendedIterator<Triple> it3 = infgraph.find(a, ty, C1);
    assertTrue(it3.hasNext());
    assertEquals(a, it3.next().getMatchSubject());
    // .. and what if we forget to call next() to consume b?
    // (e.g. return from a method with the first hit)
    // this should be enough
    it3.close();
    // without leaks of activeInterpreters
    assertEquals(0, engine.activeInterpreters.size());
}

