    boolean b = txn1.promote();
    assertTrue(b);
    AtomicReference<Transaction> ref = new AtomicReference<>(txn1);
    ThreadLib.syncOtherThread(() -> {
        // Should fail.
        Transaction txn2 = txnMgr.begin(TxnType.WRITE, false);
        ref.set(txn2);
    });
    assertNull(ref.get());
    txn1.abort();
    txn1.end();
    ThreadLib.syncOtherThread(() -> {
        // Should suceed
