    list.add("<one>");
    list.add(Integer.valueOf(5));
    Triple[] expected = { Triple.create(Node.ANY, RDF.first.asNode(), RDF.type.asNode()), Triple.create(Node.ANY, RDF.rest.asNode(), Node.ANY), Triple.create(Node.ANY, RDF.first.asNode(), NodeFactory.createURI("http://example.com/type")), Triple.create(Node.ANY, RDF.rest.asNode(), Node.ANY), Triple.create(Node.ANY, RDF.first.asNode(), NodeFactory.createURI("one")), Triple.create(Node.ANY, RDF.rest.asNode(), Node.ANY), Triple.create(Node.ANY, RDF.first.asNode(), NodeFactory.createLiteralDT("5", XSDDatatype.XSDint)), Triple.create(Node.ANY, RDF.rest.asNode(), RDF.nil.asNode()), Triple.create(Var.alloc("s"), Var.alloc("p"), Node.ANY) };
