    assertFalse(query.isDistinct());
    assertTrue(query.isReduced());
    query = builder.setDistinct(false).query;
    assertFalse(query.isDistinct());
    assertTrue(query.isReduced());
    query = builder.setDistinct(true).query;
    assertTrue(query.isDistinct());
    assertFalse(query.isReduced());
