@Test
public void simple_bearer_token() {
    String x = SimpleBearer.requestAuthorizationToken(USERNAME);
    assertFalse(x.startsWith("Bearer "));
    // No variant of base64 has ":"
    assertFalse(x.contains(":"));
    String user = SimpleBearer.getUserFromToken64(x);
    assertEquals(USERNAME, user);
}

@Test
public void simple_bearer_header() {
    String x = SimpleBearer.requestAuthorizationHeader(USERNAME);
    assertTrue(x.startsWith("Bearer "));
    String y = x.replaceFirst("^Bearer *", "");
    // No variant of base64 has ":"
    assertFalse(y.contains(":"));
    String user = SimpleBearer.getUserFromAuthHeader(x);
    assertEquals(USERNAME, user);
}

