/**
 * Test of AsGeoJSON
 */
@Test
public void testExec() throws ParseException {
    NodeValue v = NodeValue.makeNode("<gml:LineString xmlns:gml=\"http://www.opengis.net/gml/3.2\" srsName=\"EPSG:25832\">" + "<gml:posList>" + "663957.75944074022118 5103981.64908889029175 663955.915655555087142 5103991.151674075052142" + "</gml:posList>" + "</gml:LineString>", GMLDatatype.INSTANCE);
    AsGeoJSONFF instance = new AsGeoJSONFF();
    NodeValue result = instance.exec(v);
    // "{\"type\":\"LineString\",\"coordinates\":[[11.120116,46.069743],[11.120095,46.069829]]}"^^<http://www.opengis.net/ont/geosparql#geoJSONLiteral>
    NodeValue expected = NodeValue.makeNode("{\"type\":\"LineString\",\"coordinates\":[[11.12011,46.06974],[11.12009,46.06982]]}", GeoJSONDatatype.INSTANCE);
    GeometryFactory geometryFactory = new GeometryFactory();
    GeoJsonReader reader = new GeoJsonReader(geometryFactory);
    LineString expectedGeo = (LineString) reader.read(expected.asString());
    LineString actualGeo = (LineString) reader.read(result.asString());
    assertTrue("\n" + "Expected :" + String.valueOf(expectedGeo) + "\n" + "Actual   :" + String.valueOf(actualGeo) + "\n" + "Tolerance:" + String.valueOf(TOLERANCE), expectedGeo.equalsExact(actualGeo, TOLERANCE));
}

