public void testAdvancedModelImports(TestSpec spec) {
    OntModel av1 = OntModelFactory.createModel(spec.inst).setNsPrefixes(OntModelFactory.STANDARD).setID("a").setVersionIRI("v1").getModel();
    OntModel av2 = OntModelFactory.createModel(spec.inst).setNsPrefixes(OntModelFactory.STANDARD).setID("a").setVersionIRI("v2").getModel();
    OntModel b = OntModelFactory.createModel(spec.inst).setNsPrefixes(OntModelFactory.STANDARD).setID("b").getModel();
    OntModel c = OntModelFactory.createModel(spec.inst).setNsPrefixes(OntModelFactory.STANDARD).setID("c").getModel();
    try {
        c.addImport(av1).addImport(av1);
        Assertions.fail("Can add the same model");
    } catch (OntJenaException j) {
        // expected
    }
    Assertions.assertTrue(c.hasImport(av1));
    Assertions.assertFalse(c.hasImport(av2));
    Assertions.assertEquals(1, c.imports().count());
    c.removeImport(av1).addImport(av2);
    Assertions.assertTrue(c.hasImport(av2));
    Assertions.assertFalse(c.hasImport(av1));
    Assertions.assertEquals(1, c.imports().count());
    b.addImport(c);
    Assertions.assertEquals(1, b.imports().count());
    Assertions.assertTrue(b.hasImport(c));
    Assertions.assertFalse(b.hasImport(av1));
    Assertions.assertFalse(b.hasImport(av2));
    String tree = ModelTestUtils.importsTreeAsString(b.getGraph());
    Assertions.assertEquals(Arrays.asList("<b>", "<c>", "<a[v2]>"), Arrays.stream(tree.split("\n")).map(String::trim).collect(Collectors.toList()));
    c.removeImport(av1);
    tree = ModelTestUtils.importsTreeAsString(b.getGraph());
    Assertions.assertEquals(Arrays.asList("<b>", "<c>", "<a[v2]>"), Arrays.stream(tree.split("\n")).map(String::trim).collect(Collectors.toList()));
    c.removeImport(av2).addImport(av1);
    tree = ModelTestUtils.importsTreeAsString(b.getGraph());
    Assertions.assertEquals(Arrays.asList("<b>", "<c>", "<a[v1]>"), Arrays.stream(tree.split("\n")).map(String::trim).collect(Collectors.toList()));
    // sync imports:
    ((UnionGraph) c.getGraph()).addSubGraph(av2.getGraph());
    ModelTestUtils.syncImports(b);
    tree = ModelTestUtils.importsTreeAsString(b.getGraph());
    Assertions.assertEquals(4, ModelTestUtils.importsClosure(b).count());
    Assertions.assertEquals(3, ModelTestUtils.importsClosure(c).count());
    Assertions.assertEquals(Arrays.asList("<b>", "<c>", "<a[v1]>", "<a[v2]>"), Arrays.stream(tree.split("\n")).map(String::trim).collect(Collectors.toList()));
    Assertions.assertEquals(Arrays.asList("v1", "v2"), c.statements(null, OWL2.imports, null).map(Statement::getResource).map(Resource::getURI).sorted().collect(Collectors.toList()));
}

