@Test
public void testAddRemoveSubGraphs() {
    UnionGraph a = new UnionGraphImpl(createNamedGraph("a"));
    Graph b = createNamedGraph("b");
    a.addSubGraph(b);
    UnionGraph c = new UnionGraphImpl(createNamedGraph("c"));
    a.addSubGraph(c);
