    // recursion:
    d.addSubGraph(c);
    tree = ModelTestUtils.importsTreeAsString(a);
    Assertions.assertEquals(6, tree.split("\n").length);
    Graph h = createNamedGraph("H");
    c.addSubGraph(h);
