    Assertions.assertEquals(8, tree.split("\n").length);
    // remove recursion:
    d.removeSubGraph(c);
    tree = ModelTestUtils.importsTreeAsString(a);
    Assertions.assertEquals(7, tree.split("\n").length);
}

