        System.out.println("---- Different:");
        RDFDataMgr.write(System.out, m, Lang.TTL);
        System.out.println("---- ----");
        RDFDataMgr.write(System.out, m2, Lang.TTL);
        System.out.println("---- ----");
    }
    assertTrue(m.isIsomorphicWith(m2));
}

