@Test
public void visibilityOfNewlyCreatedResources() {
    Resource resource = ResourceFactory.createResource();
    assertFalse(Txn.calculateRead(dataset, () -> dataset.getDefaultModel().containsResource(resource)));
    Txn.executeWrite(dataset, () -> {
        dataset.getDefaultModel().add(resource, RDFS.label, "I exist!");
        assertTrue(dataset.getDefaultModel().containsResource(resource));
        rinseCache();
        assertTrue("A newly created resource should be visible within the write transaction", dataset.getDefaultModel().containsResource(resource));
    });
    assertTrue("A newly created resource should be visible after commit", Txn.calculateRead(dataset, () -> dataset.getDefaultModel().containsResource(resource)));
}

@Test
public void testIsolation() {
    Resource resource = ResourceFactory.createResource();
    Txn.executeWrite(dataset, () -> {
        assertFalse(dataset.getDefaultModel().containsResource(resource));
        dataset.getDefaultModel().add(resource, RDFS.label, "I exist!");
        rinseCache();
        executeAndWait(() -> Txn.executeRead(dataset, () -> dataset.getDefaultModel().containsResource(resource)));
        assertTrue("A read transaction should not pollute the nonPresent cache if there's a write transaction", dataset.getDefaultModel().containsResource(resource));
    });
}

